                        print(f"    contactType={data.get('contactType','?')} | email={data.get('email','?')}")
                    else:
                        print(f"    keys={list(data.keys())}")
                except json.JSONDecodeError as e:
                    print(f"  ✗ Block {i+1}: INVALID JSON — {str(e)[:80]}")
